// ===== Edit these settings (or override with n8n env vars). No secrets here. =====
const env = $env;
const cfg = {
  dry_run: String(env.GUARD_DRY_RUN ?? 'true').toLowerCase() !== 'false', // default: dry run ON
  timezone: env.GUARD_TIMEZONE || 'Europe/London',
  guard_slot: Number(env.GUARD_SLOT || 5),            // timer slot the guard may use (1-6)
  guard_cap_soc: Number(env.GUARD_CAP_SOC || 100),    // battery target while an extra dispatch runs
  restore_start: env.GUARD_RESTORE_START || '16:00',  // slot start time to put back afterwards (not 18:00: that is SELL_START's default)
  restore_cap_soc: Number(env.GUARD_RESTORE_CAP_SOC || 50),
  restore_grid_charge: String(env.GUARD_RESTORE_GRID_CHARGE || 'false') === 'true',
  offpeak_start: env.GUARD_OFFPEAK_START || '23:30',  // normal IO cheap window (ignored as "extra")
  offpeak_end: env.GUARD_OFFPEAK_END || '05:30',
  protected_slots: String(env.GUARD_PROTECTED_SLOTS || '1,2,3,4,6').split(',').map(Number), // never written
  ev_device_id: env.OCTOPUS_EV_DEVICE_ID || '',       // blank = first EV/charger on the account
  plug_url: env.GUARD_PLUG_STATE_URL || '',           // optional HA state URL for a plugged-in sensor; blank = gate off
  plug_on_states: String(env.GUARD_PLUG_ON_STATES || 'on,plugged_in,true').split(','),
  control_url: env.SUNSYNK_CONTROL_URL || 'http://127.0.0.1:5678/webhook/sunsynk-control',
  inverter_sn: env.SUNSYNK_INVERTER_SN || '',
  lead_in_min: Number(env.GUARD_LEAD_IN_MIN || 20),   // arm at most this many minutes before an extra dispatch starts
  slot_prev_start: env.GUARD_SLOT_PREV_START || '',   // start time of slot (GUARD_SLOT - 1) on your inverter
  slot_next_start: env.GUARD_SLOT_NEXT_START || '',   // start time of slot (GUARD_SLOT + 1); 00:00 if GUARD_SLOT is 6
  alert_workflow_id: String(env.GUARD_ALERT_WORKFLOW_ID || '').trim(), // optional n8n workflow to call when Octopus fails; blank = no alert
};
const hm = /^([01]\d|2[0-3]):[0-5]\d$/;
const errs = [];
if (!(cfg.guard_slot >= 1 && cfg.guard_slot <= 6)) errs.push('GUARD_SLOT must be 1-6');
if (cfg.protected_slots.includes(cfg.guard_slot)) errs.push('GUARD_SLOT is listed in GUARD_PROTECTED_SLOTS');
if (!(cfg.lead_in_min >= 0 && cfg.lead_in_min <= 120)) errs.push('GUARD_LEAD_IN_MIN must be 0-120');
for (const k of ['slot_prev_start', 'slot_next_start']) if (cfg[k] && !hm.test(cfg[k])) errs.push(`${k} must be HH:MM`);
if (!cfg.dry_run && (!cfg.slot_prev_start || !cfg.slot_next_start)) errs.push('Set GUARD_SLOT_PREV_START and GUARD_SLOT_NEXT_START before turning dry run off');
for (const k of ['restore_start', 'offpeak_start', 'offpeak_end']) if (!hm.test(cfg[k])) errs.push(`${k} must be HH:MM`);
for (const k of ['guard_cap_soc', 'restore_cap_soc']) if (!(cfg[k] >= 10 && cfg[k] <= 100)) errs.push(`${k} must be 10-100`);
// Slot starts must be distinct and in order. Only slot 1 (prev = slot 6, the day before) and slot 6
// (next = slot 1, the day after) may wrap past midnight.
const wraps = cfg.guard_slot === 1 || cfg.guard_slot === 6;
const between = (a, t, b) => (a < b ? a < t && t < b : wraps && (t > a || t < b));
const p0 = cfg.slot_prev_start, n0 = cfg.slot_next_start, r0 = cfg.restore_start;
if (p0 && n0 && hm.test(p0) && hm.test(n0) && hm.test(r0)) {
  if (p0 === n0) errs.push(`GUARD_SLOT_PREV_START and GUARD_SLOT_NEXT_START are a duplicate slot start (${p0})`);
  else if (r0 === p0 || r0 === n0) errs.push(`GUARD_RESTORE_START ${r0} is a duplicate slot start of a neighbour slot`);
  else if (!between(p0, r0, n0)) errs.push(`GUARD_RESTORE_START ${r0} is out of slot order (must be after ${p0} and before ${n0})`);
  if (!wraps && p0 > n0) errs.push(`GUARD_SLOT_PREV_START ${p0} / GUARD_SLOT_NEXT_START ${n0} are out of slot order (only slot 1 or 6 may cross midnight)`);
}
// Evening Sell shares the inverter's timer. Cross-workflow checks only when Sell is enabled (SELL_ENABLED=true);
// a disabled Sell config (e.g. the example.env values) does not constrain the guard.
if (String(env.SELL_ENABLED || 'false') === 'true') {
  const sellStart = env.SELL_START || '18:00', sellSlot = Number(env.SELL_SLOT || 6), n = cfg.guard_slot;
  if (r0 === sellStart) errs.push(`GUARD_RESTORE_START ${r0} is the same as SELL_START (duplicate slot start)`);
  if (sellSlot === (n % 6) + 1 && n0 && n0 !== sellStart) errs.push(`Sell is slot ${sellSlot}, the next slot: GUARD_SLOT_NEXT_START (${n0}) must equal SELL_START (${sellStart})`);
  if (sellSlot === ((n + 4) % 6) + 1 && p0 && p0 !== sellStart) errs.push(`Sell is slot ${sellSlot}, the previous slot: GUARD_SLOT_PREV_START (${p0}) must equal SELL_START (${sellStart})`);
}
if (!env.OCTOPUS_API_KEY || !env.OCTOPUS_ACCOUNT) errs.push('Set OCTOPUS_API_KEY and OCTOPUS_ACCOUNT env vars');
if (!/^\d{6,12}$/.test(cfg.inverter_sn)) errs.push('Set SUNSYNK_INVERTER_SN');
if (errs.length) throw new Error('Config: ' + errs.join('; '));
return [{ json: cfg }];

// Reads Intelligent Octopus planned dispatches for the EV/charger. Any brand, not just Tesla.
// Any API or GraphQL error, or a missing field, throws: an error is never treated as "no dispatches".
// The node is set to continue on error, so n8n passes { error } on to Plan, which decides from stored state
// (and may restore the slot). Octopus Alert then fails the execution so error workflows still fire.
const cfg = $('Config').first().json;
const tries = Number($env.OCTOPUS_RETRIES || 3), delay = Number($env.OCTOPUS_RETRY_DELAY_MS ?? 2000);
async function gql(label, query, variables, token, pick) {
  let last;
  for (let i = 1; i <= tries; i++) {
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.octopus.energy/v1/graphql/', json: true,
        headers: token ? { Authorization: token } : {}, body: { query, variables } });
      if (!r || typeof r !== 'object') throw new Error('empty response');
      if (Array.isArray(r.errors) && r.errors.length) throw new Error('GraphQL error: ' + r.errors.map((e) => (e && e.message) || 'unknown').join('; '));
      if (!r.data) throw new Error('no data in response');
      const v = pick(r.data);
      if (v === undefined || v === null) throw new Error('expected field missing');
      return v;
    } catch (e) { last = e; if (i < tries && delay > 0) await new Promise((res) => setTimeout(res, delay * i)); }
  }
  throw new Error(`Octopus ${label} failed after ${tries} tries: ${last && last.message}.`);
}
const call = gql.bind(this);
const token = await call('token', 'mutation T($k:String!){obtainKrakenToken(input:{APIKey:$k}){token}}', { k: $env.OCTOPUS_API_KEY }, null, (d) => d.obtainKrakenToken && d.obtainKrakenToken.token);
let deviceId = cfg.ev_device_id;
if (!deviceId) {
  const devs = await call('devices', 'query D($a:String!){devices(accountNumber:$a){id deviceType}}', { a: $env.OCTOPUS_ACCOUNT }, token, (d) => Array.isArray(d.devices) ? d.devices : undefined);
  const ev = devs.find((x) => x && ['ELECTRIC_VEHICLES', 'CHARGE_POINTS'].includes(x.deviceType));
  if (!ev) throw new Error('No EV or charger found on the Octopus account. Set OCTOPUS_EV_DEVICE_ID.');
  deviceId = ev.id;
}
const planned = await call('flexPlannedDispatches', 'query F($id:String!){flexPlannedDispatches(deviceId:$id){start end type}}', { id: deviceId }, token, (d) => Array.isArray(d.flexPlannedDispatches) ? d.flexPlannedDispatches : undefined);
for (const x of planned) if (!x || isNaN(Date.parse(x.start)) || isNaN(Date.parse(x.end))) throw new Error('Dispatch with bad start/end.');
return [{ json: { query_ok: true, device_found: true, planned } }];

// Works out "extra" dispatches (outside the normal off-peak window) and what slot the guard should set.
const cfg = $('Config').first().json;
const oct = $('Octopus Dispatches').first().json;
// Octopus failed (the node continues on error and passes { error }): plan from stored state instead of stopping,
// so a slot armed earlier is not left armed past its dispatch.
const octOk = !!oct && oct.query_ok === true && Array.isArray(oct.planned);
const octopus_error = octOk ? null : ((oct && oct.error && (oct.error.message || oct.error)) || 'Octopus query did not succeed');
const planned = octOk ? oct.planned : [];
const TZ = cfg.timezone;
const parts = (d) => Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(d).filter((x) => x.type !== 'literal').map((x) => [x.type, x.value]));
// Wall-clock time in TZ -> instant. Iterates so it is right on either side of a clock change.
function zoned(y, mo, d, h, mi) { let u = Date.UTC(y, mo - 1, d, h, mi); for (let i = 0; i < 3; i++) { const p = parts(new Date(u)); u += Date.UTC(y, mo - 1, d, h, mi) - Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute, +p.second); } return new Date(u); }
// Calendar-day arithmetic on a local date (never "+24 hours", which is wrong on clock-change nights).
const addDays = (y, mo, d, k) => { const t = new Date(Date.UTC(y, mo - 1, d + k)); return [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate()]; };
const [osh, osm] = cfg.offpeak_start.split(':').map(Number), [oeh, oem] = cfg.offpeak_end.split(':').map(Number);
const crossesMidnight = oeh * 60 + oem <= osh * 60 + osm;
function offpeakWindows(a, b) {
  const pa = parts(a), pb = parts(b), out = [];
  const last = Date.UTC(+pb.year, +pb.month - 1, +pb.day);
  for (let k = -1; ; k++) {
    const [y, mo, d] = addDays(+pa.year, +pa.month, +pa.day, k);
    if (Date.UTC(y, mo - 1, d) > last + 864e5) break;
    const s = zoned(y, mo, d, osh, osm);
    const [ey, emo, ed] = crossesMidnight ? addDays(y, mo, d, 1) : [y, mo, d];
    out.push({ s, e: zoned(ey, emo, ed, oeh, oem) });
  }
  return out;
}
let extras = [];
for (const d of planned) {
  const s = new Date(d.start), e = new Date(d.end); if (!(e > s)) continue;
  let segs = [{ s, e }];
  for (const w of offpeakWindows(s, e)) segs = segs.flatMap((x) => (x.e <= w.s || x.s >= w.e) ? [x] : [...(x.s < w.s ? [{ s: x.s, e: w.s }] : []), ...(x.e > w.e ? [{ s: w.e, e: x.e }] : [])]);
  extras.push(...segs.filter((x) => x.e > x.s));
}
extras.sort((a, b) => a.s - b.s);
const now = new Date();
const leadMs = cfg.lead_in_min * 60000;
// Timer slots are daily HH:MM with no date, so only arm for a window that is running now or starts within
// the lead-in. A dispatch later today or tomorrow is left alone until it is close.
const active = extras.find((x) => x.e > now && x.s.getTime() - now.getTime() <= leadMs);
const upcoming = extras.find((x) => x.e > now && !(x === active));
const hhmm = (d) => { const p = parts(d); return `${String(+p.hour % 24).padStart(2, '0')}:${p.minute}`; };
const n = cfg.guard_slot;
const g = cfg.restore_grid_charge;
const restore_params = { [`sellTime${n}`]: cfg.restore_start, [`time${n}On`]: g ? '1' : '0', [`time${n}on`]: g ? 'true' : 'false', [`cap${n}`]: cfg.restore_cap_soc };
// Slot N is only valid if prev start < its start < next start (slot 6 wraps to 00:00).
// Wrap-aware: slot 1's previous slot is slot 6 from the day before, slot 6's next is slot 1 the day after.
function inOrder(t) {
  if (!cfg.slot_prev_start || !cfg.slot_next_start) return null; // unknown: allowed only in dry run (Config enforces)
  const a = cfg.slot_prev_start, b = cfg.slot_next_start;
  if (a < b) return a < t && t < b;
  return (n === 1 || n === 6) && (t > a || t < b);
}
let mode, params, reason = null;
// The armed start must stay the same for the whole dispatch: re-clamping to "now" on every poll would move it
// (14:00, 14:10, 14:20...), rewrite the timer each run and could flip to hold once now passes the next slot.
// Fix it once per dispatch (keyed by the dispatch start) in static data and reuse it on later polls.
const pstate = $getWorkflowStaticData('global');
pstate.octopus_failures = octOk ? 0 : (Number(pstate.octopus_failures) || 0) + 1;
// Without Octopus, keep an arm only if Gate And Send verified it on the inverter (committed_arm, written after a
// real read-back) for this same dispatch, and its stored end is still in the future. A planned-but-unverified arm
// (dry run, failed write, plug gate refused) or one with no stored end is restored instead.
const ca = pstate.committed_arm, sa = pstate.arm;
const keepStored = !octOk && !!sa && !!ca && ca.key === sa.key && ca.start === sa.start && ca.end === sa.end
  && !!sa.end && !isNaN(Date.parse(sa.end)) && now < new Date(sa.end);
if (active || keepStored) {
  if (active) {
    const akey = active.s.toISOString();
    if (!pstate.arm || pstate.arm.key !== akey) pstate.arm = { key: akey, start: hhmm(active.s > now ? active.s : now) };
    pstate.arm.end = active.e.toISOString();
  }
  const start = pstate.arm.start;
  const ok = inOrder(start);
  if (ok === false) { mode = 'hold'; params = null; reason = `arm start ${start} is not between slot ${n - 1} (${cfg.slot_prev_start}) and slot ${n + 1} (${cfg.slot_next_start})`; }
  else { mode = 'arm'; params = { [`sellTime${n}`]: start, [`time${n}On`]: '1', [`time${n}on`]: 'true', [`cap${n}`]: cfg.guard_cap_soc }; if (ok === null) reason = 'slot order not checked (set GUARD_SLOT_PREV_START / GUARD_SLOT_NEXT_START)'; }
} else {
  delete pstate.arm;
  mode = 'restore'; params = restore_params;
}
if (mode !== 'hold' && inOrder(restore_params[`sellTime${n}`]) === false) throw new Error('GUARD_RESTORE_START is out of slot order. Nothing was changed.');
// The dual time{n}On / time{n}on keys are deliberate: some firmware reads one, some the other.
// Never writes sellTime{n}En or any protected slot.
if (octopus_error) reason = (reason ? reason + '; ' : '') + (mode === 'arm' ? 'Octopus unavailable; keeping the stored arm until ' + pstate.arm.end : 'Octopus unavailable; restoring');
return [{ json: { mode, reason, octopus_error, octopus_failures: pstate.octopus_failures,
  arm_key: mode === 'arm' ? pstate.arm.key : null, arm_end: mode === 'arm' ? pstate.arm.end : null, extra_count: extras.length, extra_start: active ? active.s.toISOString() : null, extra_end: active ? active.e.toISOString() : null,
  next_extra_start: upcoming ? upcoming.s.toISOString() : null, params, restore_params, dry_run: cfg.dry_run } }];

// Optional plug-in gate, then sends the plan to Sunsynk Control (one call per command).
const cfg = $('Config').first().json;
const plan = $('Plan').first().json;
const state = $getWorkflowStaticData('global');
if (plan.mode === 'hold') return [{ json: { ...plan, action: 'skipped' } }];
let plugged = null, plug_error = null;
if (cfg.plug_url) {
  try {
    const s = await this.helpers.httpRequest({ url: cfg.plug_url, json: true, headers: { Authorization: `Bearer ${$env.HA_TOKEN || ''}` } });
    plugged = (s && typeof s === 'object' && typeof s.state === 'string' && s.state !== 'unavailable' && s.state !== 'unknown')
      ? cfg.plug_on_states.includes(s.state.toLowerCase()) : null;
    if (plugged === null) plug_error = 'plug state unreadable: ' + JSON.stringify(s && s.state);
  } catch (e) { plugged = null; plug_error = 'plug state request failed: ' + ((e && e.message) || 'error'); }
}
let mode = plan.mode;
// Plug gate configured but state unknown (timeout, 401, HA error): fail closed. Restore the slot and forget the
// stored dispatch start, so the next readable poll re-arms from scratch.
let reason = plan.reason;
if (mode === 'arm' && cfg.plug_url && plugged === null) { mode = 'restore'; delete state.arm; reason = 'plug gate: ' + plug_error + '; restoring instead of arming'; }
// Car unplugged: do not arm. Use the real restore settings, not the arm ones.
if (mode === 'arm' && plugged === false) mode = 'restore';
const params = mode === 'arm' ? plan.params : plan.restore_params;
if (!params) throw new Error('No parameters for mode ' + mode);
// Only write when something changes (stop marker), so the inverter is not hammered every run.
const key = JSON.stringify({ mode, params });
if (state.last === key) {
  const ca = state.committed_arm;
  if (mode !== 'arm') delete state.committed_arm;
  // Same inverter fields, but Octopus may have moved the dispatch end: carry it over, only for an arm already verified.
  else if (ca && ca.key === plan.arm_key && ca.start === params[`sellTime${cfg.guard_slot}`] && plan.arm_end) ca.end = plan.arm_end;
  return [{ json: { ...plan, mode, params, plugged, plug_error, reason, action: 'no_change' } }]; }
const n = cfg.guard_slot;
const calls = [
  { command: 'set_sell_time', params: { [`sellTime${n}`]: params[`sellTime${n}`] } },
  { command: 'set_grid_charge', params: { [`time${n}On`]: params[`time${n}On`], [`time${n}on`]: params[`time${n}on`] } },
  { command: 'set_charge_cap', params: { [`cap${n}`]: params[`cap${n}`] } },
];
const results = [];
for (const c of calls) {
  results.push(await this.helpers.httpRequest({ method: 'POST', url: cfg.control_url, json: true,
    headers: { [$env.SUNSYNK_CONTROL_HEADER_NAME || 'X-Control-Key']: $env.SUNSYNK_CONTROL_HEADER_VALUE || '' },
    body: { ...c, sn: cfg.inverter_sn, dry_run: cfg.dry_run } }));
}
// Record the marker only for a real write that Control verified by read-back (ok) and did not dry-run.
const written = !cfg.dry_run && results.every((r) => r && r.ok === true && r.dry_run === false);
if (written) state.last = key; else delete state.last;
// committed_arm = this dispatch's arm is verified on the inverter. Plan only trusts this (not its own plan)
// when Octopus is down. Anything else (restore, dry run, failed write, plug refusal) clears it.
if (mode === 'arm' && written) state.committed_arm = { key: plan.arm_key, start: params[`sellTime${n}`], end: plan.arm_end };
else delete state.committed_arm;
const action = written ? 'written' : (results.some((r) => r && r.dry_run === true) ? 'dry_run' : 'write_failed');
return [{ json: { ...plan, mode, params, plugged, plug_error, reason, action, results } }];

// Runs after Gate And Send, so any fallback restore has already been written. Never fails the execution:
// n8n saves workflow static data only when an execution succeeds, so failing here would lose the fallback state.
// Emits one alert item for Send Alert when Octopus failed and GUARD_ALERT_WORKFLOW_ID is set; otherwise nothing.
const cfg = $('Config').first().json;
const r = $('Gate And Send').first().json;
if (!r.octopus_error || !cfg.alert_workflow_id) return [];
const n = r.octopus_failures || 1;
return [{ json: {
  alert_workflow_id: cfg.alert_workflow_id,
  source: 'io-ev-guard',
  kind: 'octopus_unavailable',
  message: `Octopus unavailable (${n} consecutive run${n === 1 ? '' : 's'}): ${r.octopus_error} Fallback: mode=${r.mode}, action=${r.action}.`,
  octopus_failures: n, octopus_error: r.octopus_error, mode: r.mode, action: r.action, reason: r.reason || null,
} }];
